class Todo {
    private String what;
    private boolean done;

    Todo(String what, boolean done) {
        this.what = what;
        this.done = done;
    }

    @Override
    public String toString() {
        return (done ? "[x] " : "[ ] ") + what;
    }
}

public class Main {
    public static void main(String[] args) {
        Todo t1 = new Todo("{a}", false);
        Todo t2 = new Todo("{b}", true);
        System.out.println(t1);
        System.out.println(t2);
    }
}
